#include <bits/stdc++.h>
using namespace std;

class FlowGraph {
public:
    struct Edge {
        int to, rev;
        long long cap;
        int cst;
        Edge(int to, int rev, long long cap, int cst) : to(to), rev(rev), cap(cap), cst(cst) {}
    };

    int n;
    std::vector<std::vector<Edge>> adjacency;
    std::vector<std::pair<int, int>> edges_storage;
    std::vector<long long> potential;
    std::vector<int> prev_vertex, prev_edge;

    FlowGraph(int n) : n(n), adjacency(n), potential(n, 0), prev_vertex(n, -1), prev_edge(n, -1) {}

    int add_edge(int u, int v, long long capacity, int cost) {
        int index = (int)edges_storage.size();
        edges_storage.emplace_back(u, (int)adjacency[u].size());
        adjacency[u].emplace_back(v, (int)adjacency[v].size(), capacity, cost);
        adjacency[v].emplace_back(u, (int)adjacency[u].size() - 1, 0, -cost);
        return index;
    }

    Edge get_edge(int i) {
        auto &e = adjacency[edges_storage[i].first][edges_storage[i].second];
        auto &re = adjacency[e.to][e.rev];
        return Edge(edges_storage[i].first, e.to, e.cap + re.cap, e.cst);
    }

    std::vector<Edge> all_edges() {
        std::vector<Edge> result;
        for (int i = 0; i < (int)edges_storage.size(); ++i) {
            auto &e = adjacency[edges_storage[i].first][edges_storage[i].second];
            auto &re = adjacency[e.to][e.rev];
            result.emplace_back(edges_storage[i].first, e.to, e.cap + re.cap, e.cst);
        }
        return result;
    }

    bool _calculate_shortest_path(int s, int t, std::vector<long long> &dist) {
        dist.assign(n, LLONG_MAX);
        prev_vertex.assign(n, -1);
        prev_edge.assign(n, -1);
        std::vector<bool> visited(n, false);
        using P = std::pair<long long, int>;
        std::priority_queue<P, std::vector<P>, std::greater<P>> heap;
        dist[s] = 0;
        heap.emplace(0, s);
        while (!heap.empty()) {
            auto [d, v] = heap.top(); heap.pop();
            if (visited[v]) continue;
            visited[v] = true;
            if (v == t) break;
            for (int i = 0; i < (int)adjacency[v].size(); ++i) {
                auto &e = adjacency[v][i];
                if (visited[e.to] || e.cap == 0) continue;
                long long nd = d + e.cst + potential[v] - potential[e.to];
                if (dist[e.to] > nd) {
                    dist[e.to] = nd;
                    prev_vertex[e.to] = v;
                    prev_edge[e.to] = i;
                    heap.emplace(nd, e.to);
                }
            }
        }
        if (dist[t] == LLONG_MAX) return false;
        for (int v = 0; v < n; ++v) {
            if (visited[v]) {
                potential[v] += dist[v];
            }
        }
        return true;
    }

    std::vector<std::pair<long long, long long>> compute_flow(int s, int t, long long max_flow = (1LL << 32) - 1) {
        long long flow = 0;
        long long total_cost = 0;
        std::vector<std::pair<long long, long long>> results;
        results.emplace_back(flow, total_cost);
        std::vector<long long> dist;
        while (flow < max_flow) {
            if (!_calculate_shortest_path(s, t, dist)) break;
            long long c = max_flow - flow;
            int v = t;
            while (v != s) {
                int u = prev_vertex[v];
                auto &e = adjacency[u][prev_edge[v]];
                c = std::min(c, e.cap);
                v = u;
            }
            v = t;
            while (v != s) {
                int u = prev_vertex[v];
                auto &e = adjacency[u][prev_edge[v]];
                e.cap -= c;
                adjacency[v][e.rev].cap += c;
                v = u;
            }
            long long delta = -potential[s];
            flow += c;
            total_cost += c * delta;
            if (results.back().second == total_cost) results.pop_back();
            results.emplace_back(flow, total_cost);
        }
        return results;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    int a1, a2, a3;
    cin >> a1 >> a2 >> a3;
    int b1, b2, b3;
    cin >> b1 >> b2 >> b3;

    FlowGraph g(8);
    g.add_edge(0, 1, a1, 0);
    g.add_edge(0, 2, a2, 0);
    g.add_edge(0, 3, a3, 0);
    g.add_edge(4, 7, b1, 0);
    g.add_edge(5, 7, b2, 0);
    g.add_edge(6, 7, b3, 0);

    for (int i = 1; i <= 3; ++i) {
        for (int j = 4; j <= 6; ++j) {
            int cst = ((j - i) % 3 == 1) ? 1 : 0;
            g.add_edge(i, j, LLONG_MAX, cst);
        }
    }

    auto result = g.compute_flow(0, 7);
    long long ans1 = result.back().first;
    long long ans2 = min(a1, b2) + min(a2, b3) + min(a3, b1);
    cout << ans1 << " " << ans2 << "\n";

    return 0;
}

